<script setup>
import { onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { useAutopeer } from '../../state/autopeer';
const s=useAutopeer(),router=useRouter(); onMounted(()=>{if(!s.currentUser.value)s.bootstrap()});
</script>
<template><section class="page-heading sessions-heading"><div><p class="eyebrow">YOUR PEERINGS</p><h1>My sessions <span class="heading-count">{{s.sessionCount.value}}</span></h1><p>Live health and useful routing data for your WireGuard and BGP sessions.</p></div><mdui-button variant="outlined" :loading="s.loadingStatus.value" @click="s.loadStatus">Refresh status</mdui-button></section><section v-if="s.sessions.value.length" class="peering-rows"><article v-for="session in s.sessions.value" :key="`${session.node.id}-${session.peer.asn}`" class="peering-row"><div class="peering-node"><span class="node-avatar">AS</span><div><strong>{{session.node.peering?.display_name||session.node.name}}</strong><span>AS{{session.peer.asn}} · {{session.node.id}}</span></div></div><div class="peering-health"><strong :class="s.statusForSession(session)?.bgp?.up?'state-good':'state-unknown'"><span class="state-dot"/>{{s.statusForSession(session)?.bgp?.up?'Established':'Status unavailable'}}</strong><div class="health-lines"><span>{{session.peer.bgp_transport?.mode?.replaceAll('_',' ')}}</span><span>↓ {{s.formatBytes(s.statusForSession(session)?.wireguard?.rx_bytes)}}</span></div></div><div class="session-actions"><mdui-button variant="outlined" @click="router.push({name:s.isAdmin.value?'admin-peer':'peer',params:{node:session.node.id,asn:session.peer.asn}})">Details</mdui-button></div></article></section><section v-else class="empty-state"><h2>No peer sessions yet</h2><mdui-button variant="filled" @click="router.push({name:s.isAdmin.value?'admin-home':'home'})">Browse nodes</mdui-button></section></template>